export const HEX_MAP = 'ABCDEFGHIJKLMNUPQRSTUVWXYZabcdefghijklmnupqrstuvwxyz0123456789'

export function getRandom(max = Math.pow(2, 16)) {
  const arr = new Uint16Array(1)
  return Math.floor(window.crypto.getRandomValues(arr)[0] * (max / Math.pow(2, 16)))
}

export function UUID(length = 32) {
  return new Array(length)
    .fill(undefined)
    .map(() => HEX_MAP.charAt(getRandom(HEX_MAP.length)))
    .join('')
}

export function copy(text) {
  if (window.clipboardData) {
    window.clipboardData.setData('text', text)
  } else {
    ;(function (t) {
      document.oncopy = function (e) {
        e.clipboardData.setData('text', t)
        e.preventDefault()
        document.oncopy = null
      }
    })(text)
    document.execCommand('Copy')
  }
}

/**
 * 随机获取数组内的n个元素
 * @param arr
 * @param n
 * @returns {*}
 */
export function getRandomElements(arr, n) {
  // 先复制数组，以免修改原始数组
  const copyArr = arr.slice()

  // 如果n大于数组长度，将n设置为数组长度
  n = Math.min(n, copyArr.length)

  // 随机排序数组
  copyArr.sort(() => Math.random() - 0.5)

  // 截取数组的前n个元素
  return copyArr.slice(0, n)
}

/**
 * Formats the file size based on the given unit.
 *
 * @param {number} value - The file size value.
 * @param {string} unit - The unit of the file size (e.g., Byte, KB, MB, GB, TB).
 * @param {number} i - The number of decimal places to round the result to.
 * @param {boolean} toString - Flag to determine if the result should be returned as a string or an object.
 * @returns {string|{value: number, unit: string}} - The formatted file size string or object.
 */
export async function fetchFileAsBlob(filePath) {
  try {
    if (!filePath) throw new Error('文件路径不能为空')
    const validPath = filePath.startsWith('/') ? filePath : `/${filePath}`
    const response = await fetch(validPath)

    if (!response.ok) {
      throw new Error(`文件请求失败: ${response.status} ${response.statusText}`)
    }

    return await response.blob()
  } catch (error) {
    console.error('文件获取失败:', error.message)
    throw new Error(`无法加载文件: ${filePath}`)
  }
}

export function formatSize(value, unit = 'Byte', i = 2, toString = true) {
  const unitMap = {
    Byte: 1,
    KB: 1024,
    MB: 1024 * 1024,
    GB: 1024 * 1024 * 1024,
    TB: 1024 * 1024 * 1024 * 1024
  }

  const unitKeys = Object.keys(unitMap)
  let unitIndex = unitKeys.indexOf(unit)
  let targetValue = value / unitMap[unitKeys[unitIndex]] || 0
  let targetUnit = unitKeys[unitIndex]

  if (unitIndex >= 0) {
    while (targetValue >= 1024) {
      unitIndex++
      targetValue /= 1024
      targetUnit = unitKeys[unitIndex]
    }
    targetValue = targetValue.toFixed(i)
  }

  return toString ? `${targetValue} ${targetUnit}` : { value: parseFloat(targetValue), unit: targetUnit }
}
